-- Migration 039: Informatics 8th grade - "Spreadsheets lab" module (8 lessons).
-- GENERATED by scripts/gen-sheetslab-sql.mjs from src/lessons/sheetsLab: edit the TypeScript, then regenerate.
-- Needs 038_levels_pairs.sql (practice levels L1-L3, variants A/B, pairs). Idempotent: lessons are matched by title.

do $sheets_lab$
declare
  v_school uuid; v_owner uuid; v_course uuid; v_module uuid; v_lesson uuid; v_spec record;
begin
  select p.school_id, p.id into v_school, v_owner from public.profiles p
  where p.role in ('teacher', 'admin') order by p.created_at limit 1;
  if v_owner is null then raise exception 'Мұғалім немесе әкімші аккаунты табылмады'; end if;
  -- the lessons belong to whoever owns the 8th-grade course, so they show in that teacher's own library
  select c.owner_id, c.school_id into v_owner, v_school from public.cf_curr_courses c
  where c.title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') order by c.created_at limit 1;
  if v_owner is null then select p.school_id, p.id into v_school, v_owner from public.profiles p where p.role in ('teacher', 'admin') order by p.created_at limit 1; end if;

  select id into v_course from public.cf_curr_courses
  where title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') and school_id = v_school limit 1;
  if v_course is null then
    insert into public.cf_curr_courses (school_id, owner_id, title, subject, grade)
    values (v_school, v_owner, 'Informatics 8th grade', 'Информатика', 8) returning id into v_course;
  end if;

  select id into v_module from public.cf_curr_modules where course_id = v_course and title = $sl$Электрондық кестелер: практикум$sl$ limit 1;
  if v_module is null then
    insert into public.cf_curr_modules (course_id, title, position, kind, quarter, grade)
    values (v_course, $sl$Электрондық кестелер: практикум$sl$, 1, 'lesson', 2, 8) returning id into v_module;
  end if;

  for v_spec in select * from (values
    ($sl$1. Электрондық кестелер$sl$, $sl$Информатика$sl$, 0, $sl${"summary":"Электрондық кестенің құрылымы: ұяшық, жол, баған, парақ, ұяшық мекенжайы және диапазон.","objectives":["Кестенің негізгі элементтерін атау","Ұяшық мекенжайын оқу және диапазонның өлшемін санау"],"grade":8,"duration":"45 минут","ru":{"summary":"Структура электронной таблицы: ячейка, строка, столбец, лист, адрес ячейки и диапазон.","objectives":["Назвать основные элементы таблицы","Читать адрес ячейки и считать размер диапазона"]}}$sl$::jsonb, $sl$[{"term":"spreadsheet","definition":"Электрондық кесте — деректерді кесте түрінде сақтап, автоматты есептейтін бағдарлама · Электронная таблица — программа для хранения данных в виде таблицы и автоматических вычислений"},{"term":"cell","definition":"Ұяшық — баған мен жолдың қиылысы · Ячейка — пересечение столбца и строки"},{"term":"range","definition":"Диапазон — таңдалған ұяшықтар тобы (A1:C4) · Диапазон — выделенная группа ячеек (A1:C4)"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"1. Электрондық кестелер","subtitle":"Информатика 8-сынып · 2-тарау","ru":{"title":"1. Электронные таблицы","subtitle":"Информатика 8 класс · глава 2"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Электрондық кесте деген не?","bullets":["Электрондық кесте — деректерді жолдар мен бағандарға орналастырып, есептеуге арналған бағдарлама.","Мысалдары: Google Sheets, Microsoft Excel, LibreOffice Calc.","Басты артықшылығы: бір сан өзгерсе, соған тәуелді барлық нәтиже өздігінен қайта есептеледі.","Алғашқы кесте — VisiCalc (1979 жыл)."],"notes":"Қағаздағы кестемен салыстырыңыз: бір санды өшіріп, жиынтықты қайта қолмен есептеу керек.","ru":{"title":"Что такое электронная таблица?","bullets":["Электронная таблица — программа, где данные расположены в строках и столбцах и по ним считают.","Примеры: Google Sheets, Microsoft Excel, LibreOffice Calc.","Главное преимущество: изменилось одно число — все зависящие результаты пересчитались сами.","Первая таблица — VisiCalc (1979 год)."],"notes":"Сравните с бумажной таблицей: стёрли число — итог пересчитывать вручную."},"design":"lab","art":"recalc"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"video","title":"Видео: Google Sheets-пен алғашқы танысу","bullets":["Көру: интерфейс, құралдар тақтасы, формулалар жолы (3–4 минут).","Көргеннен кейін: баған, жол, ұяшық, парақ қайда екенін көрсет."],"notes":"Видео сілтемесін өзіңіз қосыңыз (слайд өңдегіші → сурет/сілтеме). Жүктелмесе — Google Sheets-ті тақтада тікелей көрсетіңіз.","ru":{"title":"Видео: первое знакомство с Google Sheets","bullets":["Смотрим: интерфейс, панель инструментов, строка формул (3–4 минуты).","После просмотра: покажи, где столбец, строка, ячейка, лист."],"notes":"Добавьте ссылку на видео сами (редактор слайда). Если не грузится — покажите Google Sheets прямо на доске."},"design":"lab","art":"video"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Кестенің элементтері","bullets":["Баған (column) — тігінен: A, B, C…","Жол (row) — көлденеңінен: 1, 2, 3…","Ұяшық (cell) — баған мен жолдың қиылысы. Мекенжайы: баған әрпі + жол нөмірі (B3).","Парақ (sheet) — бір жұмыс алаңы; бір файлда бірнеше парақ болады.","Белсенді ұяшық — қазір таңдалған ұяшық, оның мәні формулалар жолында көрінеді."],"ru":{"title":"Элементы таблицы","bullets":["Столбец (column) — вертикаль: A, B, C…","Строка (row) — горизонталь: 1, 2, 3…","Ячейка (cell) — пересечение столбца и строки. Адрес: буква столбца + номер строки (B3).","Лист (sheet) — одно рабочее поле; в файле может быть несколько листов.","Активная ячейка — выбранная сейчас; её содержимое видно в строке формул."]},"design":"lab","art":"anatomy"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: мекенжай және диапазон","bullets":["B3 — B бағаны мен 3-жолдың қиылысы.","Диапазон — таңдалған ұяшықтар: A1:C4 (сол жақ жоғарғы A1-ден оң жақ төменгі C4-ке дейін).","A1:C4 ішінде 3 баған × 4 жол = 12 ұяшық."],"code":"      A    B    C\n1   [A1] [B1] [C1]\n2   [A2] [B2] [C2]\n3   [A3] [B3] [C3]\n4   [A4] [B4] [C4]   ← A1:C4 = 12 ұяшық","lang":"text","ru":{"title":"Пример: адрес и диапазон","bullets":["B3 — пересечение столбца B и строки 3.","Диапазон — выделенные ячейки: A1:C4 (от левой верхней A1 до правой нижней C4).","В A1:C4: 3 столбца × 4 строки = 12 ячеек."]},"design":"lab","art":"range"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал тапсырма: диапазон өлшемі","sections":[{"h":"Шарты","text":"B2:D5 диапазонында неше ұяшық бар?"},{"h":"Алгоритм (қадамдар)","bullets":["Бағандарды санайды: B, C, D — 3 баған.","Жолдарды санайды: 2, 3, 4, 5 — 4 жол.","Көбейтеді: 3 × 4."]},{"h":"Шешімі","text":"12 ұяшық.","hide":true}],"ru":{"title":"Задача с разбором: размер диапазона","sections":[{"h":"Условие","text":"Сколько ячеек в диапазоне B2:D5?"},{"h":"Алгоритм (шаги)","bullets":["Считаем столбцы: B, C, D — 3 столбца.","Считаем строки: 2, 3, 4, 5 — 4 строки.","Умножаем: 3 × 4."]},{"h":"Решение","text":"12 ячеек.","hide":true}]},"design":"lab","art":"range"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: кесте элементтері","prompt":"E7 мекенжайы қай ұяшықты білдіреді?","options":["E жолы, 7-баған","E бағаны, 7-жол","E және 7 ұяшықтары","7 парақтың E ұяшығы"],"answer":1,"explanation":"Алдымен баған әрпі, кейін жол нөмірі жазылады.","points":1,"ru":{"title":"Тест: элементы таблицы","prompt":"Какую ячейку обозначает адрес E7?","options":["строка E, столбец 7","столбец E, строка 7","ячейки E и 7","ячейка E листа 7"],"explanation":"Сначала буква столбца, затем номер строки."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","sheet":{"rows":10,"cols":6},"title":"Практика: кестемен танысу","prompt":"Төмендегі кестеде тапсырмаларды орында. Жауабын өріске жаз. L1 орындалмайынша L2 ашылмайды.","levels":[{"lv":1,"points":1,"title":"Мекенжай","variants":[{"v":"A","prompt":"B3 ұяшығы қай бағанда және қай жолда тұр? «баған,жол» түрінде жаз (мысалы: C,5).","accept":["b,3","b, 3","b 3"]},{"v":"B","prompt":"E7 ұяшығы қай бағанда және қай жолда тұр? «баған,жол» түрінде жаз (мысалы: C,5).","accept":["e,7","e, 7","e 7"]}]},{"lv":2,"points":2,"title":"Диапазон","variants":[{"v":"A","prompt":"A1:C4 диапазонында неше ұяшық бар?","accept":["12"]},{"v":"B","prompt":"B2:E3 диапазонында неше ұяшық бар?","accept":["8"]}]},{"lv":3,"points":3,"title":"Таңдау және қосынды","variants":[{"v":"A","prompt":"A1-ге 5, A2-ге 7, A3-ке 9 енгіз. A1:A3 диапазонын тышқанмен таңда — кесте төменгі жағында «Қосынды» (Sum) көрсетеді. Қосындысы қанша?","accept":["21"]},{"v":"B","prompt":"A1-ге 4, A2-ге 6, A3-ке 8 енгіз. A1:A3 диапазонын тышқанмен таңда — төменгі жағындағы «Қосынды» мәні қанша?","accept":["18"]}]}],"ru":{"title":"Практика: знакомство с таблицей","prompt":"Выполните задания в таблице ниже. Ответ введите в поле. Пока не выполнен L1, L2 не откроется.","levels":[{"lv":1,"points":1,"title":"Адрес","variants":[{"v":"A","prompt":"В каком столбце и строке находится ячейка B3? Ответ вида «столбец,строка» (например: C,5)."},{"v":"B","prompt":"В каком столбце и строке находится ячейка E7? Ответ вида «столбец,строка» (например: C,5)."}]},{"lv":2,"points":2,"title":"Диапазон","variants":[{"v":"A","prompt":"Сколько ячеек в диапазоне A1:C4?"},{"v":"B","prompt":"Сколько ячеек в диапазоне B2:E3?"}]},{"lv":3,"points":3,"title":"Выделение и сумма","variants":[{"v":"A","prompt":"Введите в A1 5, в A2 7, в A3 9. Выделите диапазон A1:A3 мышью — таблица покажет внизу «Сумма» (Sum). Чему она равна?"},{"v":"B","prompt":"Введите в A1 4, в A2 6, в A3 8. Выделите A1:A3 мышью — чему равна «Сумма» внизу?"}]}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: диапазон","prompt":"Төмендегілердің қайсысы диапа